traceability.evidence:
Implementation and tests clearly cover all requirements of docs/stories/010.1-DEV-CONFIGURABLE-PATTERNS.story.md.

Key implementation files:

1) src/rules/helpers/valid-annotation-options.ts
- Declares the configuration interface with both nested and flat options, matching the story's RuleOptions shape and extending it:
  ```ts
  export interface AnnotationRuleOptions {
    story?: { pattern?: string; example?: string };
    req?: { pattern?: string; example?: string };

    // Flat shorthand options per story
    storyPathPattern?: string;
    storyPathExample?: string;
    requirementIdPattern?: string;
    requirementIdExample?: string;
  }
  ```
- Provides default, hardcoded patterns and examples (backward-compatible behavior):
  ```ts
  function getDefaultStoryPattern(): RegExp {
    return /^docs\/stories\/[0-9]+\.[0-9]+-DEV-[\w-]+\.story\.md$/;
  }
  function getDefaultStoryExample(): string {
    return "docs/stories/005.0-DEV-EXAMPLE.story.md";
  }
  function getDefaultReqPattern(): RegExp {
    return /^REQ-[A-Z0-9-]+$/;
  }
  export function getDefaultReqExample(): string {
    return "REQ-EXAMPLE";
  }
  ```
- Tracks and exposes resolved defaults and configuration errors:
  ```ts
  let resolvedDefaults: ResolvedAnnotationOptions = { ... };
  let optionErrors: string[] = [];

  export function getResolvedDefaults(): ResolvedAnnotationOptions {
    return resolvedDefaults;
  }

  export function getOptionErrors(): string[] {
    return optionErrors;
  }
  ```
- Normalizes user options and supports both nested and flat configuration shapes:
  ```ts
  function normalizeUserOptions(rawOptions: unknown[]): AnnotationRuleOptions | undefined {
    if (!rawOptions || rawOptions.length === 0) return undefined;
    const first = rawOptions[0];
    if (!first || typeof first !== "object") return undefined;
    return first as AnnotationRuleOptions;
  }
  ```
- Validates custom regex patterns for both story and requirement IDs, including the flat shorthand fields, with clear error messages and safe fallback to defaults:
  ```ts
  function buildInvalidRegexError(field: string, pattern: string): string {
    return `Invalid regular expression for option "${field}": "${pattern}"`;
  }

  function resolvePattern({ nestedPattern, nestedFieldName, flatPattern, flatFieldName, defaultPattern }: ResolvePatternArgs): RegExp {
    const effective =
      typeof nestedPattern === "string"
        ? { value: nestedPattern, field: nestedFieldName }
        : typeof flatPattern === "string"
          ? { value: flatPattern, field: flatFieldName }
          : null;

    if (!effective) {
      return defaultPattern; // backward-compatible behavior when no pattern is configured
    }

    try {
      return new RegExp(effective.value);
    } catch {
      optionErrors.push(buildInvalidRegexError(effective.field, effective.value));
      return defaultPattern; // fallback to defaults on invalid regex
    }
  }
  ```
- Resolves example strings, preferring nested over flat, with default fallback; this powers the improved error messages for custom patterns:
  ```ts
  function resolveExample(
    nestedExample: string | undefined,
    flatExample: string | undefined,
    defaultExample: string,
  ): string {
    if (typeof nestedExample === "string" && nestedExample.trim()) return nestedExample;
    if (typeof flatExample === "string" && flatExample.trim()) return flatExample;
    return defaultExample;
  }
  ```
- Main `resolveOptions` function wires everything together, providing a `ResolvedAnnotationOptions` object that the rule uses at runtime:
  ```ts
  export function resolveOptions(rawOptions: unknown[]): ResolvedAnnotationOptions {
    optionErrors = [];

    const user = normalizeUserOptions(rawOptions);

    const nestedStoryPattern = user?.story?.pattern;
    const flatStoryPattern = user?.storyPathPattern;
    const nestedStoryExample = user?.story?.example;
    const flatStoryExample = user?.storyPathExample;

    const nestedReqPattern = user?.req?.pattern;
    const flatReqPattern = user?.requirementIdPattern;
    const nestedReqExample = user?.req?.example;
    const flatReqExample = user?.requirementIdExample;

    const storyPattern = resolvePattern({
      nestedPattern: nestedStoryPattern,
      nestedFieldName: "story.pattern",
      flatPattern: flatStoryPattern,
      flatFieldName: "storyPathPattern",
      defaultPattern: getDefaultStoryPattern(),
    });

    const reqPattern = resolvePattern({
      nestedPattern: nestedReqPattern,
      nestedFieldName: "req.pattern",
      flatPattern: flatReqPattern,
      flatFieldName: "requirementIdPattern",
      defaultPattern: getDefaultReqPattern(),
    });

    const storyExample = resolveExample(nestedStoryExample, flatStoryExample, getDefaultStoryExample());
    const reqExample = resolveExample(nestedReqExample, flatReqExample, getDefaultReqExample());

    resolvedDefaults = { storyPattern, storyExample, reqPattern, reqExample };
    return resolvedDefaults;
  }
  ```
- Provides JSON Schema for ESLint rule options, including the new pattern/example fields, satisfying REQ-SCHEMA-VALIDATION and the "Quality Standards" acceptance criterion:
  ```ts
  export function getRuleSchema() {
    return [
      {
        type: "object",
        properties: {
          story: {
            type: "object",
            properties: {
              pattern: { type: "string" },
              example: { type: "string" },
            },
            additionalProperties: false,
          },
          req: {
            type: "object",
            properties: {
              pattern: { type: "string" },
              example: { type: "string" },
            },
            additionalProperties: false,
          },
          storyPathPattern: { type: "string" },
          storyPathExample: { type: "string" },
          requirementIdPattern: { type: "string" },
          requirementIdExample: { type: "string" },
        },
        additionalProperties: false,
      },
    ];
  }
  ```
- File header explicitly ties this helper to Story 010.1 requirements:
  ```ts
  /**
   * Shared option handling for the valid-annotation-format rule.
   *
   * @story docs/stories/010.1-DEV-CONFIGURABLE-PATTERNS.story.md
   * @req REQ-PATTERN-CONFIG - Support configuration of custom story path and requirement ID patterns
   * @req REQ-REGEX-VALIDATION - Validate that configured patterns are valid regular expressions
   * @req REQ-BACKWARD-COMPAT - Maintain current behavior when no custom patterns configured
   * @req REQ-EXAMPLE-MESSAGES - Support optional example strings in error messages
   * @req REQ-SCHEMA-VALIDATION - Use JSON Schema to validate configuration options
   */
  ```

2) src/rules/helpers/valid-annotation-utils.ts
- Uses the resolved examples from configuration (including custom examples) when constructing error messages, fulfilling REQ-EXAMPLE-MESSAGES:
  ```ts
  export function buildStoryErrorMessage(
    kind: "missing" | "invalid",
    value: string | null,
    options: ResolvedAnnotationOptions,
  ): string {
    const example = options.storyExample || STORY_EXAMPLE_PATH;
    if (kind === "missing") {
      return `Missing story path for @story annotation. Expected a path like "${example}".`;
    }
    return `Invalid story path "${value ?? ""}" for @story annotation. Expected a path like "${example}".`;
  }

  export function buildReqErrorMessage(
    kind: "missing" | "invalid",
    value: string | null,
    options: ResolvedAnnotationOptions,
  ): string {
    const example = options.reqExample || getDefaultReqExample();
    if (kind === "missing") {
      return `Missing requirement ID for @req annotation. Expected an identifier like "${example}".`;
    }
    return `Invalid requirement ID "${value ?? ""}" for @req annotation. Expected an identifier like "${example}" (uppercase letters, numbers, and dashes only).`;
  }
  ```

3) src/rules/valid-annotation-format.ts
- Imports the shared options helper and schema:
  ```ts
  import {
    getResolvedDefaults,
    resolveOptions,
    type ResolvedAnnotationOptions,
    getRuleSchema,
