  ```
- Uses the configured patterns (`options.storyPattern`, `options.reqPattern`) when validating annotations, ensuring custom patterns control validation:
  ```ts
  function validateStoryAnnotation(
    context: any,
    comment: any,
    rawValue: string,
    options: ResolvedAnnotationOptions,
  ): void {
    const trimmed = rawValue.trim();
    if (!trimmed) {
      context.report({
        node: comment as any,
        messageId: "invalidStoryFormat",
        data: { details: buildStoryErrorMessage("missing", null, options) },
      });
      return;
    }

    const collapsed = collapseAnnotationValue(trimmed);
    const pathPattern = options.storyPattern;

    if (pathPattern.test(collapsed)) {
      return;
    }
    // ... auto-fix path suffix and fallback behavior ...
  }

  function validateReqAnnotation(
    context: any,
    comment: any,
    rawValue: string,
    options: ResolvedAnnotationOptions,
  ): void {
    const trimmed = rawValue.trim();
    if (!trimmed) {
      context.report({
        node: comment as any,
        messageId: "invalidReqFormat",
        data: { details: buildReqErrorMessage("missing", null, options) },
      });
      return;
    }

    const collapsed = collapseAnnotationValue(trimmed);
    const reqPattern = options.reqPattern;

    if (!reqPattern.test(collapsed)) {
      context.report({
        node: comment as any,
        messageId: "invalidReqFormat",
        data: { details: buildReqErrorMessage("invalid", collapsed, options) },
      });
    }
  }
  ```
- Adds a dedicated configuration error message `invalidRuleConfiguration` to surface invalid regex patterns, per REQ-REGEX-VALIDATION and acceptance criterion "Pattern Validation":
