- In the rule `create` function, resolves options and then reports any configuration errors collected while still proceeding to validate comments with safe default patterns (backwards-compatible behavior):
  ```ts
  create(context: any) {
    const sourceCode = context.getSourceCode();
    const options = resolveOptions(context.options || []);
    const optionErrors = getOptionErrors();

    return {
      Program(node: any) {
        if (optionErrors && optionErrors.length > 0) {
          optionErrors.forEach((details: string) => {
            context.report({
              node,
              messageId: "invalidRuleConfiguration",
              data: { details },
            });
          });
        }

        const comments = sourceCode.getAllComments() || [];
        comments.forEach((comment: any) => {
          processComment(context, comment, options);
        });
      },
    };
  },
  ```
- Rule- and function-level JSDoc explicitly reference the story and its requirements, including the 010.1 story:
